/**
 * Area bundle: **screens, first half** — `screens/Account.tsx` through
 * `screens/Group.tsx` alphabetically, which is where the whole `Admin*`
 * studio-side suite lives (AdminCal, AdminClients, AdminMarketing,
 * AdminPayroll, AdminPos, AdminReports, AdminReviews, AdminServices,
 * AdminSettings, AdminStock, AdminTeam, AdminToday) plus Account, Blog,
 * Booking, Careers, Checkout, Confirm, Dash, Event, ExportData, GiftCards
 * and Group.
 *
 * Add keys to all eight locales at once. See `chrome.ts` for the plural-variant
 * order each locale expects; shared counted nouns (`count.*`) already live
 * there — reuse them rather than re-declaring them here.
 *
 * In-fiction demo content is deliberately absent: service and treatment names,
 * staff and client names, blog bodies, review text, gift codes, package names
 * and addresses stay English (18-marketplace-launch.md §3.4). Everything here
 * is product chrome.
 */
